//go:build amd64

package floats

// The AVX2 kernel of the conjugate-reverse (conjrev.go), generated by go-asmgen
// (conjrev_amd64_gen.go) into conjrev_amd64.s: four complex numbers per step, for a
// CPU with the AVX2+FMA of the other kernels (hasAVX2FMA, kernels_amd64.go); the
// portable loop otherwise. The Go code finishes the last numbers. No kernel keeps a
// pointer: go:noescape.
//
//go:noescape
func conjRevAVX2(dst, src []float64)

func conjReverse(dst, src []float64) {
	if !hasAVX2FMA {
		conjRevTail(dst, src, 0)
		return
	}
	conjRevAVX2(dst, src)
	conjRevTail(dst, src, (len(dst)/2)&^3)
}
